"""TASK-051 R2 shared DbD Training Studio video transport."""
from __future__ import annotations
from dataclasses import dataclass
from typing import Callable
from enum import Enum
import json
from pathlib import Path
import subprocess
import time

from .dbd_training_diagnostics import DiagnosticLogger, get_diagnostic_logger

class VideoTransportState(str, Enum):
    STOPPED="STOPPED"; PLAYING="PLAYING"; REWINDING="REWINDING"; FAST_FORWARDING="FAST_FORWARDING"

STATE_JA={VideoTransportState.STOPPED:"停止",VideoTransportState.PLAYING:"再生中",VideoTransportState.REWINDING:"巻き戻し中",VideoTransportState.FAST_FORWARDING:"早送り中"}

@dataclass(frozen=True, slots=True)
class VideoTransportEvent:
    action: str
    state: VideoTransportState
    frame_index: int
    position_seconds: float
    source: str


@dataclass(frozen=True, slots=True)
class VideoTransportMetadata:
    fps_numerator:int
    fps_denominator:int
    duration_seconds:float
    total_frames:int
    @property
    def fps(self): return self.fps_numerator/self.fps_denominator
    @property
    def last_frame(self): return max(0,self.total_frames-1)
    @property
    def frame_interval_ms(self): return max(1,round(1000.0/self.fps))

def _parse_rate(value):
    raw=(value or "").strip()
    if not raw or raw=="0/0": raise ValueError("video FPS is unavailable")
    if "/" in raw:
        a,b=raw.split("/",1); n,d=int(a),int(b)
    else:
        n,d=int(float(raw)*1000),1000
    if n<=0 or d<=0: raise ValueError("video FPS must be positive")
    return n,d

def metadata_from_ffprobe_payload(payload):
    streams=payload.get("streams") or []
    if not streams: raise ValueError("ffprobe returned no video stream")
    stream=streams[0]
    n,d=_parse_rate(stream.get("avg_frame_rate") or stream.get("r_frame_rate"))
    fps=n/d
    raw_duration=stream.get("duration")
    if raw_duration in (None,"","N/A"): raw_duration=(payload.get("format") or {}).get("duration")
    duration=float(raw_duration or 0)
    raw_frames=stream.get("nb_frames")
    if raw_frames not in (None,"","N/A"): total=int(raw_frames)
    else:
        if duration<=0: raise ValueError("video duration/frame count is unavailable")
        total=max(1,round(duration*fps))
    if total<=0: raise ValueError("video frame count must be positive")
    if duration<=0: duration=total/fps
    return VideoTransportMetadata(n,d,duration,total)

def probe_video_metadata(source_path, *, ffprobe_executable="ffprobe"):
    source=Path(source_path)
    if not source.is_file(): raise ValueError("video source does not exist")
    cmd=[ffprobe_executable,"-v","error","-select_streams","v:0","-show_entries","stream=avg_frame_rate,r_frame_rate,nb_frames,duration:format=duration","-of","json",str(source)]
    try:
        cp=subprocess.run(cmd,stdout=subprocess.PIPE,stderr=subprocess.PIPE,check=False,timeout=30)
    except (OSError,subprocess.TimeoutExpired) as exc:
        raise RuntimeError("ffprobeで動画情報を取得できませんでした") from exc
    if cp.returncode:
        raise RuntimeError("ffprobeで動画情報を取得できませんでした: "+cp.stderr.decode("utf-8",errors="replace").strip())
    return metadata_from_ffprobe_payload(json.loads(cp.stdout.decode("utf-8")))



def playback_frame_for_elapsed(
    metadata: VideoTransportMetadata,
    *,
    anchor_frame: int,
    state: VideoTransportState,
    elapsed_seconds: float,
) -> int:
    """Resolve continuous transport position from a monotonic-clock anchor.

    The result depends on elapsed wall time rather than the number of completed
    UI callbacks, so slow preview rendering cannot make playback permanently
    drift behind the source timeline.
    """
    elapsed = max(0.0, float(elapsed_seconds))
    if state is VideoTransportState.STOPPED:
        return min(max(0, int(anchor_frame)), metadata.last_frame)
    rate = {
        VideoTransportState.PLAYING: 1.0,
        VideoTransportState.REWINDING: -1.0,
        VideoTransportState.FAST_FORWARDING: 4.0,
    }[state]
    delta = round(elapsed * metadata.fps * rate)
    return min(max(0, int(anchor_frame) + delta), metadata.last_frame)

class VideoTransportModel:
    def __init__(self,metadata,frame_index=0):
        self.metadata=metadata; self.frame_index=self._clamp(frame_index); self.state=VideoTransportState.STOPPED
    def _clamp(self,v): return min(max(0,int(v)),self.metadata.last_frame)
    def set_frame(self,v): self.frame_index=self._clamp(v); return self.frame_index
    def stop(self): self.state=VideoTransportState.STOPPED
    def first(self): self.stop(); return self.set_frame(0)
    def last(self): self.stop(); return self.set_frame(self.metadata.last_frame)
    def step_frames(self,d): self.stop(); return self.set_frame(self.frame_index+int(d))
    def step_seconds(self,s): return self.step_frames(round(float(s)*self.metadata.fps))
    def play(self): self.state=VideoTransportState.PLAYING
    def rewind(self): self.state=VideoTransportState.REWINDING
    def fast_forward(self): self.state=VideoTransportState.FAST_FORWARDING
    def tick(self):
        if self.state is VideoTransportState.STOPPED: return self.frame_index
        delta=-1 if self.state is VideoTransportState.REWINDING else (4 if self.state is VideoTransportState.FAST_FORWARDING else 1)
        nxt=self._clamp(self.frame_index+delta)
        if nxt==self.frame_index: self.stop(); return self.frame_index
        self.frame_index=nxt
        if self.frame_index in (0,self.metadata.last_frame): self.stop()
        return self.frame_index
    def position_seconds(self): return self.frame_index/self.metadata.fps

ICON_PNG_BASE64 = {"minus_10s": "", "minus_1s": "", "minus_1f": "", "first": "", "rewind": "", "stop": "", "play": "", "fast_forward": "", "last": "", "plus_1f": "", "plus_1s": "", "plus_10s": ""}
BUTTON_LAYOUT=(
("first","最初へ"),("rewind","巻き戻し"),("stop","停止"),("play","再生"),("fast_forward","早送り"),("last","最後へ"),
("minus_10s","-10秒"),("minus_1s","-1秒"),("minus_1f","-1フレーム"),("plus_1f","+1フレーム"),("plus_1s","+1秒"),("plus_10s","+10秒"),
)

class TkVideoTransportBar:
    def __init__(
        self, parent, *, root, source_getter, frame_getter, frame_setter,
        render_frame, ffprobe_executable="ffprobe", title="動画操作",
        clock=time.monotonic, maximum_preview_fps=30.0,
        diagnostics: DiagnosticLogger | None = None,
        diagnostic_feature: str = "TRAINING_VIDEO",
        player_id: str = "shared-video",
        state_listener: Callable[[VideoTransportEvent], None] | None = None,
    ):
        import tkinter as tk
        from tkinter import ttk
        if maximum_preview_fps <= 0:
            raise ValueError("maximum_preview_fps must be positive")
        self.root=root; self.source_getter=source_getter; self.frame_getter=frame_getter; self.frame_setter=frame_setter
        self.render_frame=render_frame; self.ffprobe_executable=ffprobe_executable; self.model=None; self.source_identity=None; self.after_id=None
        self.clock=clock; self.maximum_preview_fps=float(maximum_preview_fps)
        self.diagnostics=diagnostics or get_diagnostic_logger(); self.diagnostic_feature=str(diagnostic_feature); self.player_id=str(player_id)
        self.state_listener=state_listener
        self._clock_anchor_time=None; self._clock_anchor_frame=None
        self.icons={k:tk.PhotoImage(data=v) for k,v in ICON_PNG_BASE64.items()}
        self.frame=ttk.LabelFrame(parent,text=title,padding=6)
        for c in range(6): self.frame.columnconfigure(c,weight=1)
        self.position_text=tk.StringVar(value="動画を選択してください。")
        ttk.Label(self.frame,textvariable=self.position_text,anchor="w").grid(row=2,column=0,columnspan=6,sticky="ew",pady=(4,0))
        self.seek_var=tk.DoubleVar(value=0.0)
        self._seek_dragging=False
        ttk.Label(self.frame,text="タイムシーク").grid(row=3,column=0,sticky="w",pady=(4,0))
        self.seek_scale=ttk.Scale(
            self.frame, from_=0.0, to=1000.0, orient="horizontal",
            variable=self.seek_var, command=self._preview_seek,
        )
        self.seek_scale.grid(row=3,column=1,columnspan=5,sticky="ew",pady=(4,0))
        self.seek_scale.bind("<ButtonPress-1>",self._seek_press,add="+")
        self.seek_scale.bind("<ButtonRelease-1>",self._seek_release,add="+")
        actions={"first":self.first,"rewind":self.rewind,"stop":self.stop,"play":self.play,"fast_forward":self.fast_forward,"last":self.last,
                 "minus_10s":lambda:self.jump_seconds(-10),"minus_1s":lambda:self.jump_seconds(-1),"minus_1f":lambda:self.jump_frames(-1),
                 "plus_1f":lambda:self.jump_frames(1),"plus_1s":lambda:self.jump_seconds(1),"plus_10s":lambda:self.jump_seconds(10)}
        for i,(key,label) in enumerate(BUTTON_LAYOUT):
            row=0 if i<6 else 1; col=i if i<6 else i-6
            ttk.Button(self.frame,image=self.icons[key],text=label,compound="top",command=actions[key]).grid(row=row,column=col,sticky="nsew",padx=2,pady=2)
    def grid(self,**kw): self.frame.grid(**kw)
    def _cancel(self):
        if self.after_id is not None:
            try:self.root.after_cancel(self.after_id)
            except Exception:pass
            self.after_id=None
    def _clear_clock_anchor(self):
        self._clock_anchor_time=None; self._clock_anchor_frame=None
    def _anchor_clock(self):
        if self.model is None:return
        self._clock_anchor_time=self.clock(); self._clock_anchor_frame=self.model.frame_index
    def _ensure(self):
        source=self.source_getter().strip()
        if not source: raise ValueError("先に動画を選択してください。")
        if self.model is None or source!=self.source_identity:
            self._cancel(); self._clear_clock_anchor(); self.model=VideoTransportModel(probe_video_metadata(source,ffprobe_executable=self.ffprobe_executable),self.frame_getter()); self.source_identity=source
        elif self.model.state is VideoTransportState.STOPPED:
            self.model.set_frame(self.frame_getter())
        self._sync(); return self.model
    def _sync(self):
        if self.model is None:
            self.position_text.set("動画を選択してください。"); return
        self.frame_setter(self.model.frame_index)
        if not self._seek_dragging:
            denominator=max(1,self.model.metadata.last_frame)
            self.seek_var.set(1000.0*self.model.frame_index/denominator)
        self.position_text.set(f"{STATE_JA[self.model.state]} / フレーム {self.model.frame_index+1:,} / {self.model.metadata.total_frames:,} / {self.model.position_seconds():.3f}秒 / {self.model.metadata.fps:.3f} fps")
    def _seek_press(self,_event=None):
        self._seek_dragging=True
        self._cancel()
    def _preview_seek(self,value):
        if not self._seek_dragging or self.model is None:return
        fraction=min(1.0,max(0.0,float(value)/1000.0))
        frame=round(self.model.metadata.last_frame*fraction)
        seconds=frame/self.model.metadata.fps
        self.position_text.set(f"シーク先 / フレーム {frame+1:,} / {self.model.metadata.total_frames:,} / {seconds:.3f}秒")
    def _seek_release(self,_event=None):
        try:
            m=self._ensure()
            self._cancel(); self._clear_clock_anchor()
            fraction=min(1.0,max(0.0,float(self.seek_var.get())/1000.0))
            m.set_frame(round(m.metadata.last_frame*fraction)); m.stop()
            self.diagnostics.emit(
                "TRANSPORT_ACTION", feature=self.diagnostic_feature, player_id=self.player_id,
                action="seek_bar", frame_index=m.frame_index, source=self.source_identity or "",
            )
            self._render(); self._notify_state("seek_bar")
        except Exception as exc:
            self.diagnostics.exception(
                "TRANSPORT_SEEK_FAILED", exc, feature=self.diagnostic_feature, player_id=self.player_id,
            )
            self.position_text.set(f"タイムシークできません: {exc}")
        finally:
            self._seek_dragging=False
            self._sync()
    def _notify_state(self, action):
        if self.model is None or self.state_listener is None:
            return
        event=VideoTransportEvent(
            action=str(action), state=self.model.state, frame_index=self.model.frame_index,
            position_seconds=self.model.position_seconds(), source=self.source_identity or "",
        )
        try:
            self.state_listener(event)
        except Exception as exc:
            self.diagnostics.exception(
                "TRANSPORT_STATE_LISTENER_FAILED", exc, feature=self.diagnostic_feature,
                player_id=self.player_id, action=str(action), frame_index=self.model.frame_index,
            )
    def _render(self): self.frame_setter(self.model.frame_index); self._sync(); self.render_frame(self.model.frame_index)
    def _refresh_interval_ms(self):
        if self.model is None:return 33
        source_interval=self.model.metadata.frame_interval_ms
        capped=max(1,round(1000.0/self.maximum_preview_fps))
        if self.model.state is VideoTransportState.REWINDING:
            return max(100, source_interval)
        if self.model.state is VideoTransportState.FAST_FORWARDING:
            return max(50, source_interval)
        return max(capped, source_interval)
    def _schedule(self):
        self._cancel()
        if self.model.state is VideoTransportState.STOPPED:self._sync();return
        self.after_id=self.root.after(self._refresh_interval_ms(),self._tick)
    def _tick(self):
        self.after_id=None
        if self.model is None or self.model.state is VideoTransportState.STOPPED:return
        if self._clock_anchor_time is None or self._clock_anchor_frame is None:self._anchor_clock()
        elapsed=self.clock()-self._clock_anchor_time
        target=playback_frame_for_elapsed(
            self.model.metadata,
            anchor_frame=self._clock_anchor_frame,
            state=self.model.state,
            elapsed_seconds=elapsed,
        )
        self.diagnostics.emit(
            "PLAYBACK_TICK", level="DEBUG", feature=self.diagnostic_feature,
            player_id=self.player_id, state=self.model.state.name,
            current_frame=self.model.frame_index, target_frame=target, elapsed_seconds=elapsed,
        )
        if target!=self.model.frame_index:
            self.model.frame_index=target; self._render()
        else:self._sync()
        if target in (0,self.model.metadata.last_frame):
            self.model.stop(); self._clear_clock_anchor(); self._sync(); self._notify_state("boundary-stop"); return
        self._schedule()
    def _manual(self, action, *, action_name="manual"):
        m=self._ensure(); self._cancel(); self._clear_clock_anchor(); value=action(m)
        self.diagnostics.emit(
            "TRANSPORT_ACTION", feature=self.diagnostic_feature, player_id=self.player_id,
            action=action_name, frame_index=m.frame_index, source=self.source_identity or "",
        )
        self._render(); self._notify_state(action_name); return value
    def first(self): return self._manual(lambda m:m.first(), action_name="first")
    def last(self): return self._manual(lambda m:m.last(), action_name="last")
    def jump_frames(self,d): return self._manual(lambda m:m.step_frames(d), action_name=f"jump_frames:{d}")
    def jump_seconds(self,s): return self._manual(lambda m:m.step_seconds(s), action_name=f"jump_seconds:{s}")
    def stop(self):
        self._cancel(); self._clear_clock_anchor(); self.model.stop() if self.model is not None else None
        self.diagnostics.emit(
            "TRANSPORT_ACTION", feature=self.diagnostic_feature, player_id=self.player_id,
            action="stop", frame_index=(self.model.frame_index if self.model is not None else None),
            source=self.source_identity or "",
        )
        self._sync(); self._notify_state("stop")
    def _start_continuous(self, starter, *, action_name):
        m=self._ensure(); self._cancel(); starter(m); self._anchor_clock()
        self.diagnostics.emit(
            "PLAYBACK_CLOCK_STARTED", feature=self.diagnostic_feature, player_id=self.player_id,
            action=action_name, frame_index=m.frame_index, state=m.state.name,
            source=self.source_identity or "",
        )
        self._sync(); self._notify_state(action_name); self._schedule()
    def play(self): self._start_continuous(lambda m:m.play(), action_name="play")
    def rewind(self): self._start_continuous(lambda m:m.rewind(), action_name="rewind")
    def fast_forward(self): self._start_continuous(lambda m:m.fast_forward(), action_name="fast_forward")
